		name    string
		handler http.HandlerFunc
		want    string
	}{
		{
			name: "list fails",
			handler: func(w http.ResponseWriter, r *http.Request) {
				http.Error(w, "nope", http.StatusForbidden)
			},
			want: "list comments: github: GET /repos/o/r/issues/9/comments: 403 Forbidden: nope\n",
		},
		{
